Upsert Case From Lab Result.code:
// Create or update a case in an outbreak, matched on visualId.
upsertCase(
  // 1) Outbreak id. Pass a string: this argument is not read from state.
  '3b5554d7-2c19-41d0-b9af-475ad25a382b',
  // 2) Case field used to find an existing record.
  'visualId',
  // 3) The case to write.
  {
    visualId: $.data.caseId,
    firstName: $.data.firstName,
    lastName: $.data.lastName,
    gender: 'LNG_REFERENCE_DATA_CATEGORY_GENDER_FEMALE',
    age: { years: $.data.ageYears },
    classification: 'LNG_REFERENCE_DATA_CATEGORY_CASE_CLASSIFICATION_CONFIRMED',
    dateOfReporting: $.data.reportedOn,
    dateOfOnset: $.data.symptomOnset,
    addresses: [
      {
        typeId: 'LNG_REFERENCE_DATA_CATEGORY_ADDRESS_TYPE_USUAL_PLACE_OF_RESIDENCE',
        locationId: $.data.locationId,
        phoneNumber: $.data.phone,
      },
    ],
  }
);

Upsert Contact.code:
// Create or update a contact in an outbreak, matched on visualId.
upsertContact(
  // 1) Outbreak id (string literal).
  '3b5554d7-2c19-41d0-b9af-475ad25a382b',
  // 2) Contact field used to find an existing record.
  'visualId',
  // 3) The contact to write.
  {
    visualId: $.data.contactId,
    firstName: $.data.firstName,
    lastName: $.data.lastName,
    gender: 'LNG_REFERENCE_DATA_CATEGORY_GENDER_MALE',
    dateOfReporting: $.data.reportedOn,
    dateOfLastContact: $.data.lastExposure,
    riskLevel: 'LNG_REFERENCE_DATA_CATEGORY_RISK_LEVEL_HIGH',
    addresses: [
      {
        typeId: 'LNG_REFERENCE_DATA_CATEGORY_ADDRESS_TYPE_USUAL_PLACE_OF_RESIDENCE',
        locationId: $.data.locationId,
        phoneNumber: $.data.phone,
      },
    ],
  }
);

Upsert Location From Facility Registry.code:
// Create or update a location, matched on its name.
upsertLocation(
  // 1) Location field used to find an existing record.
  'name',
  // 2) The location to write.
  {
    name: $.data.facilityName,
    // Go.Data id of the parent district or region.
    parentLocationId: $.data.parentLocationId,
    geographicalLevelId: 'LNG_REFERENCE_DATA_CATEGORY_LOCATION_GEOGRAPHICAL_LEVEL_ADMIN_LEVEL_3',
    identifiers: [{ code: $.data.orgUnitCode, description: 'DHIS2 org unit code' }],
    geoLocation: { lat: $.data.latitude, lng: $.data.longitude },
    active: true,
  }
);

Upsert Outbreak.code:
// Create or update an outbreak. externalId is matched against the outbreak's id.
upsertOutbreak({
  externalId: $.data.outbreakId,
  data: {
    name: 'Cholera 2026 - Northern Region',
    description: 'Outbreak response opened after district alert.',
    disease: 'LNG_REFERENCE_DATA_CATEGORY_DISEASE_CHOLERA',
    startDate: $.data.declaredOn,
    periodOfFollowup: 14,
  },
});

Upsert Reference Data Item.code:
// Create or update a reference data item, matched on its value.
upsertReferenceData(
  // 1) Reference data field used to find an existing record.
  'value',
  // 2) The reference data item to write.
  {
    categoryId: 'LNG_REFERENCE_DATA_CATEGORY_CENTRE_NAME',
    value: $.data.centreName,
    code: $.data.centreCode,
    description: 'Synced from the national facility registry',
    active: true,
  }
);

Find Confirmed Cases.code:
// Find confirmed cases in an outbreak using a Loopback "where" filter.
getCase(
  // 1) Outbreak id (string literal).
  '3b5554d7-2c19-41d0-b9af-475ad25a382b',
  // 2) Filter sent as ?filter=...
  {
    where: {
      classification: 'LNG_REFERENCE_DATA_CATEGORY_CASE_CLASSIFICATION_CONFIRMED',
      dateOfReporting: { gte: '2026-10-01' },
    },
  }
);

Find Contact By Visual ID.code:
// Find a contact by visualId.
getContact(
  // 1) Outbreak id (string literal).
  '3b5554d7-2c19-41d0-b9af-475ad25a382b',
  // 2) Loopback filter.
  { where: { visualId: 'CON-2026-00042' } }
);

List Reference Data By Category.code:
// Get all reference data items in one category (here: case classifications).
getReferenceData({
  where: { categoryId: 'LNG_REFERENCE_DATA_CATEGORY_CASE_CLASSIFICATION' },
});
